import{bQ as s,aL as e,u as n,G as l}from"./chunks/framework.DaEK0KQB.js";const u=JSON.parse('{"title":"快应用内使用eslint","description":"","frontmatter":{"title":"快应用内使用eslint","date":"2023-07-10T15:49:16.000Z","permalink":"/pages/d72731/","categories":["多端","快应用"],"tags":[null]},"headers":[],"relativePath":"多端/快应用/08.快应用内使用eslint.md","filePath":"多端/快应用/08.快应用内使用eslint.md","lastUpdated":1787100298000}'),i={name:"多端/快应用/08.快应用内使用eslint.md"};function t(p,a,r,c,d,o){return e(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="快应用内使用eslint" tabindex="-1">快应用内使用eslint <a class="header-anchor" href="#快应用内使用eslint" aria-label="Permalink to &quot;快应用内使用eslint&quot;">​</a></h1><p><a href="https://zh-hans.eslint.org/" target="_blank" rel="noreferrer"><strong>eslint 中文文档地址</strong></a></p><h2 id="eslint大家都说好" tabindex="-1">eslint大家都说好 <a class="header-anchor" href="#eslint大家都说好" aria-label="Permalink to &quot;eslint大家都说好&quot;">​</a></h2><h3 id="_1-安装eslint" tabindex="-1">1. 安装eslint <a class="header-anchor" href="#_1-安装eslint" aria-label="Permalink to &quot;1. 安装eslint&quot;">​</a></h3><p><code>npm i eslint --save-dev</code></p><h3 id="_2-安装快应用专属plugin" tabindex="-1">2. 安装快应用专属plugin <a class="header-anchor" href="#_2-安装快应用专属plugin" aria-label="Permalink to &quot;2. 安装快应用专属plugin&quot;">​</a></h3><p><code>npm i eslint-plugin-ux --save-dev</code></p><h3 id="_3-创建一个-eslintignore文件-将-替换为任何一个字符" tabindex="-1">3. 创建一个.eslintignore文件，将*替换为任何一个字符 <a class="header-anchor" href="#_3-创建一个-eslintignore文件-将-替换为任何一个字符" aria-label="Permalink to &quot;3. 创建一个.eslintignore文件，将*替换为任何一个字符&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/.nyc_output</span></span>
<span class="line"><span>/coverage</span></span>
<span class="line"><span>/node_modules</span></span>
<span class="line"><span>/tests/fixtures</span></span>
<span class="line"><span>/sign</span></span>
<span class="line"><span>/dist</span></span>
<span class="line"><span>/build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_4-创建eslint配置文件" tabindex="-1">4. 创建eslint配置文件 <a class="header-anchor" href="#_4-创建eslint配置文件" aria-label="Permalink to &quot;4. 创建eslint配置文件&quot;">​</a></h3><p>可以直接从外部拷贝过来自己使用的 <code>.eslintrc.json</code></p><p>也可以通过命令的方式来加载</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx eslint --init //初始化一个eslint配置文件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="https://cdn.jsdelivr.net/gh/akcshen/chartBed@master/assets/img/202307201738504.png" alt="image-20230720173830274"></p><ul><li>只检查语法</li><li>检查语法并提示问题 👈</li><li>检查语法、提示问题并且强制使用一些代码风格</li></ul><p><img src="https://cdn.jsdelivr.net/gh/akcshen/chartBed@master/assets/img/202307201740832.png" alt="image-20230720174008795"></p><ul><li>javaScriptModel ES6模块 👈</li><li>CommenJs Nodejs使用的模块规范 CommonJS采用同步加载模块的方式，只有加载完才能执行后面的操做，主要适用于服务端 ES6语法的项目选择第一个，否则选择第二个</li></ul><p><img src="https://cdn.jsdelivr.net/gh/akcshen/chartBed@master/assets/img/202307201742208.png" alt="image-20230720174201185"></p><p><img src="https://cdn.jsdelivr.net/gh/akcshen/chartBed@master/assets/img/202307201742305.png" alt="image-20230720174232278"></p><p><img src="https://cdn.jsdelivr.net/gh/akcshen/chartBed@master/assets/img/202307201742221.png" alt="image-20230720174248199"></p><ul><li>选择你的选项目是在浏览器运行还是node上运行（上下箭头移动到想要的选项上，点击空格键进行选中，此处可多选，将两个选项都选中）</li></ul><p><img src="https://cdn.jsdelivr.net/gh/akcshen/chartBed@master/assets/img/202307201743703.png" alt="image-20230720174359679"></p><ul><li>选择以什么样的格式形成你的配置文件（此处我选择JS）</li></ul><img src="https://cdn.jsdelivr.net/gh/akcshen/chartBed@master/assets/img/202307201744882.png" alt="image-20230720174453858" style="zoom:30%;"><ul><li>工程目录下的.eslint.js文件即刚刚新创建的eslint配置文件</li></ul><h3 id="_5-安装快应用hap-eslint插件-配置为保存自动格式化" tabindex="-1">5. 安装快应用hap-eslint插件，配置为保存自动格式化 <a class="header-anchor" href="#_5-安装快应用hap-eslint插件-配置为保存自动格式化" aria-label="Permalink to &quot;5. 安装快应用hap-eslint插件，配置为保存自动格式化&quot;">​</a></h3><h3 id="_6-eslint的配置项" tabindex="-1">6. eslint的配置项 <a class="header-anchor" href="#_6-eslint的配置项" aria-label="Permalink to &quot;6. eslint的配置项&quot;">​</a></h3><h4 id="_1-globals对象" tabindex="-1">1. globals对象： <a class="header-anchor" href="#_1-globals对象" aria-label="Permalink to &quot;1. globals对象：&quot;">​</a></h4><p>当访问当前源文件内未定义的变量时，no-undef 规则将发出警告,如果你想在一个源文件里使用全局变量，推荐你在 ESLint 中定义这些全局变量，这样 ESLint 就不会发出警告了。你可以使用注释或在配置文件中定义全局变量。</p><ul><li>通过注释的方法</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* global var1, var2 */</span></span>
<span class="line"><span>这定义了两个全局变量，var1 和 var2。如果你想选择性地指定这些全局变量可以被写入(而不是只被读取)，那么你可以用一个 &quot;writable&quot; 的标志来设置它们:</span></span>
<span class="line"><span>/* global var1:writable, var2:writable */</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>通过globals的配置项</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用于定义一些没有声明的全局变量，</span></span>
<span class="line"><span>取值：</span></span>
<span class="line"><span>readonly/false——只读</span></span>
<span class="line"><span>writable/true——可写</span></span>
<span class="line"><span>off——禁用该全局变量</span></span>
<span class="line"><span>说明：true/false 等价于只读/可写，但不推荐使用。</span></span>
<span class="line"><span>由于历史原因，布尔值 false 和字符串值 &quot;readable&quot; 等价于 &quot;readonly&quot;。类似地，布尔值 true 和字符串值 &quot;writeable&quot; 等价于 &quot;writable&quot;。但是，不建议使用旧值。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div>`,33)])])}const b=s(i,[["render",t]]);export{u as __pageData,b as default};
